FICHES.append(fiche(
 id='salles-de-shoot-delinquance', affirmation="Les salles de shoot attirent les dealers et la délinquance.", volet='securite', sous_theme='Sécurité du quotidien',
 mots_cles=['salles de shoot delinquance', 'salle de shoot dealers', 'halte soins addictions', 'salle de consommation a moindre risque', 'salle de shoot gare du nord', 'salle de shoot riverains', 'salle de shoot insecurite', 'shooting room', 'salle de shoot strasbourg', 'pas de salle de shoot chez nous'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. L'évaluation de l'Inserm publiée en 2021 n'a constaté aucune détérioration de la tranquillité publique autour des salles de Paris et de Strasbourg, et les usagers qui y ont accès commettent moins de délits ; autour de la salle parisienne, les seringues abandonnées sont passées d'environ 150 à moins de 10 par jour. Mais la salle parisienne, installée dans un quartier où la consommation de rue existait déjà, suscite toujours des plaintes de riverains (bagarres, déchets, injections dehors). Aucune source lue ne montre que les salles attirent le trafic.",
 contexte="Deux haltes soins addictions fonctionnent à titre expérimental depuis 2016, près de la gare du Nord à Paris et à Strasbourg. L'expérimentation a été prolongée jusqu'à fin 2027. Chaque projet d'ouverture dans une autre ville suscite une opposition locale, souvent nourrie par l'idée qu'une salle ferait venir dealers et délinquants.",
 explication="On s'appuie sur l'évaluation scientifique de l'Inserm (via la presse et un rapport parlementaire), sur les travaux parlementaires et sur ce qu'on sait du rapport des inspections générales de 2024, en séparant tranquillité publique, délinquance des usagers et ressenti des riverains.",
 sources=[A_SC_LOCALTIS, A_SC_AN2021, A_SC_PS, A_SC_FA, A_SC_QE, A_SC_SM],
 faits=[
  fait("Selon la Banque des Territoires, qui rapporte l'évaluation de l'Inserm de mai 2021, l'étude conclut à « une absence de détérioration de la tranquillité publique » depuis l'ouverture des salles de Paris et de Strasbourg.", 'a_sc_localtis', '2016-2021', 'Paris et Strasbourg', "La principale évaluation scientifique ne trouve pas l'effet redouté sur le quartier.", 'etabli'),
  fait("Selon la même source, parmi 665 usagers suivis pendant un an, l'accès à une salle réduit l'injection en extérieur de 15 % et les passages aux urgences de 24 %, et diminue la probabilité de commettre des délits.", 'a_sc_localtis', '2016-2021', 'Paris et Strasbourg', "Les usagers des salles consomment moins dans la rue et commettent moins de délits que ceux qui n'y ont pas accès.", 'etabli', '-15 %'),
  fait("Selon la mission flash de l'Assemblée nationale (septembre 2021), menée par une députée de la majorité et un député LR, le nombre de seringues retrouvées dans le quartier de la salle parisienne a été divisé par trois, et les données de l'Inserm « tendent à montrer » l'absence de dégradation de la tranquillité publique.", 'a_sc_an2021', '2016-2021', 'Paris', "Des parlementaires de bords différents tirent le même constat.", 'etabli'),
  fait("Selon Public Sénat, les rapports de l'IGAS, de l'IGA et de l'Inserm concluent à une réduction des nuisances dans l'espace public ; autour de la halte parisienne, les seringues abandonnées sont passées de 150 à moins de 10 par jour.", 'a_sc_ps', '2016-2025', 'Paris', "Les inspections de l'État confirment l'effet sur l'espace public.", 'etabli', '150 à moins de 10'),
  fait("Selon les associations gestionnaires, le rapport IGA-IGAS d'octobre 2024 juge les haltes utiles « sans équivoque » pour la tranquillité publique, et les policiers et magistrats auditionnés y voient un moyen de réduire les « nuisances et délits liés à la consommation visible ».", 'a_sc_fa', '2024', 'Paris et Strasbourg', "Les acteurs de la sécurité eux-mêmes défendraient le dispositif ; la source étant partie prenante, ce point reste à vérifier dans le rapport.", 'interpretation'),
  fait("Fait défavorable : selon la Banque des Territoires, la salle parisienne continue de susciter des plaintes de riverains (bagarres, accumulation de déchets, injections pratiquées en extérieur), alors que celle de Strasbourg, installée dans un hôpital, fait plutôt consensus.", 'a_sc_localtis', '2021', 'Paris', "Une salle ne fait pas disparaître la misère et la consommation de rue d'un quartier déjà touché : l'emplacement et la médiation comptent.", 'etabli'),
 ],
 court="Ce n'est pas ce que montrent les évaluations. Selon l'Inserm, les salles de Paris et Strasbourg n'ont pas dégradé la tranquillité publique, les usagers commettent moins de délits et les seringues abandonnées autour de la salle parisienne sont passées d'environ 150 à moins de 10 par jour. Les nuisances persistent à Paris, mais elles existaient avant : la salle ne les a pas créées.",
 moyen="Les deux salles françaises ont été évaluées de près. Selon l'Inserm, en 2021, il n'y a pas eu de détérioration de la tranquillité publique autour de Paris et de Strasbourg. Les usagers qui ont accès à une salle s'injectent moins dans la rue (-15 %), vont moins aux urgences (-24 %) et commettent moins de délits. Autour de la halte parisienne, les seringues abandonnées sont passées de 150 à moins de 10 par jour.\n\nLa salle de la gare du Nord reste critiquée par des riverains : bagarres, déchets, injections dehors. Mais elle a été installée là où la consommation de rue existait déjà ; à Strasbourg, dans un hôpital, elle fait plutôt consensus. Aucune des sources lues ne montre qu'une salle attire le trafic : le deal suit les consommateurs, pas les lieux de soin.",
 detaille="L'idée qu'une salle de consommation attirerait dealers et délinquants est l'argument le plus fréquent contre les haltes soins addictions. Or les deux salles françaises, ouvertes en 2016 à Paris et à Strasbourg, ont fait l'objet d'une évaluation scientifique de l'Inserm publiée en 2021.\n\nSelon cette évaluation, rapportée par la Banque des Territoires, il n'y a pas eu de détérioration de la tranquillité publique depuis l'ouverture des salles. Sur 665 usagers suivis pendant un an, l'accès à une salle réduit les injections en extérieur de 15 %, les passages aux urgences de 24 % et la probabilité de commettre des délits. La mission flash de l'Assemblée nationale, conduite en 2021 par une députée de la majorité et un député LR, relève que le nombre de seringues retrouvées dans le quartier parisien a été divisé par trois. Selon Public Sénat, qui résume les rapports de l'Inserm et des inspections générales, les seringues abandonnées autour de la salle parisienne sont passées de 150 à moins de 10 par jour.\n\nLa loi encadre d'ailleurs strictement les abords : seul le transport d'une quantité destinée à la consommation personnelle y est toléré, le trafic reste poursuivi.\n\nIl ne faut pas pour autant nier le malaise d'une partie des riverains de la gare du Nord : bagarres, déchets, injections encore pratiquées dehors. Mais cette salle a été placée dans un quartier où la consommation de rue était déjà massive, et elle ne peut pas à elle seule régler la misère et le crack. À Strasbourg, dans l'enceinte d'un hôpital, la salle fait plutôt consensus. La leçon est plutôt de mieux choisir les lieux, d'ouvrir plusieurs petites structures et de renforcer la médiation, comme le font de nombreux pays européens voisins, qui comptent plus de cent cinquante espaces de ce type.",
 empathie="Vivre près d'une scène de consommation de drogue, avec ses seringues, ses bagarres et sa détresse, est éprouvant. Il est normal de craindre qu'une salle aggrave la situation : la question mérite des réponses précises.",
 legitimes=["Des riverains de la salle parisienne subissent des nuisances réelles, documentées par l'évaluation elle-même.", "Une salle ne règle pas seule le problème de la consommation de rue et du trafic dans un quartier.", "Les habitants doivent être associés au choix de l'emplacement et au suivi."],
 contre=[
  ("Depuis la salle, le quartier de la gare du Nord est devenu invivable.", "La consommation de rue y existait avant ; selon l'Inserm, il n'y a pas eu de détérioration de la tranquillité publique, et les seringues abandonnées ont fortement diminué."),
  ("Les salles de shoot, c'est une zone de non-droit pour les dealers.", "Le trafic reste poursuivi : aux abords, seul le transport d'une petite quantité pour usage personnel est toléré, selon la mission de l'Assemblée nationale."),
  ("Ça encourage à se droguer.", "Les salles accueillent des personnes déjà dépendantes ; elles réduisent les overdoses, les passages aux urgences et la consommation dans la rue, selon l'Inserm."),
 ],
 questions=["Sans salle, où crois-tu que les personnes dépendantes s'injecteraient : chez elles, ou dans ta cage d'escalier ?", "Qu'est-ce qui te gênerait le plus : une salle encadrée par des soignants, ou des seringues dans la rue ?"],
 limites=["Le rapport de l'Inserm (2021) n'a pas pu être ouvert (serveur indisponible) : ses résultats sont rapportés par la Banque des Territoires, la mission flash de l'Assemblée nationale et Public Sénat.", "Le rapport IGA-IGAS de 2024 n'a pas été lu : il est connu par le communiqué des associations gestionnaires (partie prenante) et par Public Sénat.", "Aucune source lue ne mesure spécifiquement le trafic de drogue aux abords des salles : l'absence d'effet repose sur l'indicateur global de tranquillité publique.", "Les données portent sur deux salles seulement, dans des contextes très différents."],
 publics={'convaincus': "Je comprends la crainte, mais regarde ce qu'ont trouvé les chercheurs de l'Inserm : pas de dégradation de la tranquillité publique, et des usagers qui commettent moins de délits. Autour de la salle parisienne, on est passé de 150 seringues ramassées par jour à moins de 10. Les drogués et les dealers étaient là avant la salle : elle ne les a pas fait venir.",
  'indecis': "Les nuisances autour de la salle de Paris sont réelles, et les riverains ont raison de se plaindre. Mais l'évaluation scientifique montre que la salle n'a pas aggravé la situation et qu'elle a fait reculer les seringues et l'injection dans la rue. À Strasbourg, dans un hôpital, ça se passe bien : tout dépend de l'endroit et des moyens."},
 a_actualiser='2027-12-31', raison="Fin de l'expérimentation des haltes soins addictions prévue fin 2027 et nouvelle évaluation des Hospices civils de Lyon.",
))

# 4 ── « Les délinquants sont de plus en plus jeunes » ──────────────
A_MIN_SENAT = ('a_min_senat', src("Prévenir la délinquance des mineurs, éviter la récidive (rapport d'information n° 885, 2021-2022) — Ce que disent les chiffres de la délinquance des mineurs", 'Sénat, commissions de la culture et des lois (Céline Boulay-Espéronnier, Bernard Fialaire, Laurence Harribey, Muriel Jourda)', '21 septembre 2022',
  'https://www.senat.fr/rap/r21-885/r21-8856.html',
  "La part des mineurs parmi les mis en cause est passée de 14 % à 20 % entre 1992 et 2002, puis s'est stabilisée autour de 18 % jusqu'en 2019. Parmi les mineurs mis en cause, la part des 15-17 ans passe de 63,1 % (2016) à 67,3 % (2021), celle des 13-14 ans de 25,0 % à 22,0 %, et celle des moins de 13 ans recule. Seul élément local : à Avignon, guetteurs et revendeurs seraient « fréquemment âgés de 13 ans au lieu de 15 ans ». De 2016 à 2021 : vols sans violence -28,4 %, vols violents -14,9 %, violences sexuelles sur mineurs +59,7 %, mineurs mis en cause pour trafic +35,15 %.",
  "Rapport d'information transpartisan du Sénat.", 'primaire'))
