 mots_cles=['trump washington criminalite', 'garde nationale washington', 'trump a nettoye washington', 'washington crime baisse trump', 'national guard dc', 'trump securite washington', 'plus de meurtres a washington', 'trump ordre washington', 'il faut faire comme trump', 'armee dans les villes'],
