FICHES.append(fiche(
 id='harcelement-de-rue-invention', affirmation="Le harcèlement de rue est une invention des féministes.", volet='droits', sous_theme='Violences faites aux femmes',
 mots_cles=['harcelement de rue invention', 'harcelement de rue n existe pas', 'on ne peut plus draguer', 'les feministes exagerent', 'outrage sexiste', 'harcelement dans les transports', 'siffler une femme', 'drague lourde', 'neo feministes harcelement', 'loi schiappa harcelement de rue'],
 verdict='contredit', fiabilite='etabli',
 resume="Faux. Le harcèlement dans l'espace public est mesuré par la statistique publique, pas seulement dénoncé par des militantes. Selon l'enquête Virage de l'Ined, un quart des femmes ont subi au moins un fait de violence dans l'espace public en un an, le plus souvent des sifflements ou interpellations « de drague » non désirés. Depuis la loi de 2018, police et gendarmerie enregistrent ces faits : environ 3 900 en 2025 selon le SSMSI, avec 90 % de victimes femmes et des auteurs presque toujours des hommes. Certains chiffres militants circulent sans méthode solide, mais le phénomène, lui, est établi.",
 contexte="L'expression « harcèlement de rue » s'est diffusée dans les années 2010 grâce à des associations féministes et des témoignages en ligne, puis la loi du 3 août 2018 a créé l'outrage sexiste. Une partie de la droite et de l'extrême droite y voit une invention qui criminaliserait la drague, tout en accusant parfois les seuls immigrés d'en être les auteurs.",
 explication="On s'appuie sur les enquêtes de victimation (qui interrogent directement la population), sur les infractions enregistrées par la police et la gendarmerie, et on examine honnêtement les chiffres militants les plus fragiles.",
 sources=[D_HR_INED, D_HR_CHA, D_HR_SSMSI, D_HR_IGPN, D_HR_MAIRE, D_HR_DALLOZ, D_HR_HCE],
 faits=[
  fait("Selon l'Ined (enquête Virage, 2015), environ un quart des femmes ont subi au moins un fait de violence dans l'espace public au cours des douze derniers mois ; pour 100 femmes, 20 ont été sifflées ou interpellées sous prétexte de drague, 8 insultées et 3 suivies.", 'd_hr_ined', '2015', 'France métropolitaine', "C'est une enquête scientifique représentative, menée par un institut public : le phénomène est mesuré, pas inventé.", 'etabli', '25 %'),
  fait("Selon la synthèse de l'enquête Virage publiée par le Centre Hubertine Auclert et l'Ined, 37 % des Franciliennes et 68 % des Franciliennes de 20 à 25 ans ont subi au moins un fait de violence dans l'espace public en un an ; seuls 3 % des Franciliens ont subi de la drague importune, contre 29 % des Franciliennes.", 'd_hr_cha', '2015', 'Île-de-France', "Ce harcèlement vise d'abord les jeunes femmes, et presque pas les hommes : c'est bien une violence liée au sexe.", 'etabli', '68 %'),
  fait("Selon le SSMSI, environ 90 % des victimes d'outrages sexistes enregistrés en 2018-2020 étaient des femmes, et 93 % des personnes mises en cause étaient des hommes majeurs ; les faits se produisaient surtout sur la voie publique ou dans les transports.", 'd_hr_ssmsi', '2018-2020', 'France', "Les données de la police confirment le profil décrit par les enquêtes.", 'etabli', '90 %'),
  fait("Selon le SSMSI, cité par Maire-info, police et gendarmerie ont enregistré environ 3 900 infractions d'outrage sexiste ou sexuel en 2025, en hausse de 17 % sur un an ; 90 % des victimes sont des femmes, et ce chiffre sous-estime la réalité faute de plaintes.", 'd_hr_maire', '2025', 'France', "Des milliers de faits sont constatés chaque année malgré un taux de plainte très faible.", 'estimation', '3 900'),
  fait("Selon l'Inspection générale de la police nationale (2021), la loi du 3 août 2018 a créé l'outrage sexiste, qui « comble un vide juridique » ; l'enquête Cadre de vie et sécurité de 2017 indique qu'une victime de violences sexistes et sexuelles sur dix seulement porte plainte.", 'd_hr_igpn', '2017-2021', 'France', "Les chiffres enregistrés ne sont que la partie visible : la plupart des victimes ne portent pas plainte.", 'etabli'),
  fait("Selon Dalloz Actualité, depuis le 1er avril 2023, l'outrage sexiste et sexuel simple est une contravention de 5e classe, et sa forme aggravée est devenue un délit avec la loi du 24 janvier 2023.", 'd_hr_dalloz', '2023', 'France', "Le législateur, sous des majorités de droite et du centre, a reconnu et durci la répression de ces comportements.", 'etabli'),
  fait("Fait défavorable : selon le Haut Conseil à l'égalité (2015), le chiffre souvent repris de « 100 % des utilisatrices des transports » victimes de harcèlement provient de consultations auprès d'environ 600 participantes, qui ne constituent pas un échantillon représentatif.", 'd_hr_hce', '2015', 'France', "Ce chiffre ne doit pas être présenté comme une mesure statistique ; les enquêtes représentatives donnent des ordres de grandeur plus bas, mais déjà très élevés.", 'etabli', '100 %'),
 ],
 court="Non. Ce n'est pas une impression militante : selon l'enquête Virage de l'Ined, un quart des femmes subissent au moins un fait de violence dans l'espace public en un an, surtout des sifflements et interpellations non désirés. Depuis 2018, la loi punit l'outrage sexiste ; en 2025, environ 3 900 faits ont été enregistrés, avec 90 % de victimes femmes, alors que très peu de victimes portent plainte.",
 moyen="Le harcèlement de rue est mesuré par des enquêtes scientifiques. Selon l'enquête Virage de l'Ined, un quart des femmes ont subi au moins un fait de violence dans l'espace public dans l'année : sifflements et interpellations sous prétexte de drague pour 20 femmes sur 100, insultes pour 8, filatures pour 3. En Île-de-France, c'est le cas de 68 % des femmes de 20 à 25 ans, contre très peu d'hommes.\n\nLa police et la gendarmerie le constatent aussi. Depuis la loi de 2018, l'outrage sexiste est une infraction : environ 3 900 faits ont été enregistrés en 2025, selon le SSMSI, avec 90 % de victimes femmes et des mis en cause presque toujours des hommes. Et ce n'est qu'une petite partie, puisqu'une victime sur dix seulement porte plainte. Certains chiffres militants, comme « 100 % des usagères », reposent sur des témoignages non représentatifs : mais les enquêtes sérieuses confirment l'ampleur du phénomène.",
 detaille="Pour savoir si un phénomène existe, la statistique publique interroge directement la population. L'enquête Virage, menée en 2015 par l'Institut national d'études démographiques, montre qu'environ un quart des femmes ont subi au moins un fait de violence dans l'espace public au cours des douze derniers mois. Les faits les plus fréquents sont les sifflements et interpellations sous prétexte de drague (20 femmes sur 100), les insultes (8 sur 100) et le fait d'être suivie (3 sur 100). Au cours de leur vie, 7,9 % des femmes ont subi une agression sexuelle dans l'espace public. En Île-de-France, 68 % des femmes de 20 à 25 ans déclarent au moins un fait dans l'année, alors que seuls 3 % des hommes franciliens subissent de la drague importune.\n\nLes données de police vont dans le même sens. La loi du 3 août 2018 a créé l'outrage sexiste, qui « comble un vide juridique » selon l'Inspection générale de la police nationale. Selon le SSMSI, environ 90 % des victimes sont des femmes, 93 % des mis en cause sont des hommes majeurs, et les faits se produisent surtout dans la rue et les transports. En 2025, environ 3 900 infractions ont été enregistrées, en hausse de 17 %. C'est très peu au regard des enquêtes, car une victime sur dix seulement porte plainte et l'auteur est rarement identifié. Depuis 2023, la forme aggravée est un délit.\n\nIl faut être honnête sur un point : certains chiffres qui circulent, comme « 100 % des usagères des transports », viennent de consultations militantes non représentatives, comme le précise le Haut Conseil à l'égalité lui-même. Ils ne sont pas nécessaires : les enquêtes sérieuses suffisent à établir l'ampleur du problème.\n\nLe harcèlement de rue n'a donc rien d'une invention. Il restreint la liberté de circuler des femmes, surtout des plus jeunes. Le combattre, c'est défendre l'égalité et la liberté de toutes, quelle que soit l'origine des auteurs, sans en faire un prétexte pour stigmatiser une population.",
 empathie="Beaucoup d'hommes se demandent sincèrement où passe la limite entre aborder quelqu'un et le harceler, et craignent d'être accusés à tort. Cette inquiétude mérite une réponse claire plutôt que du mépris.",
 legitimes=["La frontière entre une approche courtoise et du harcèlement peut sembler floue pour certains.", "Certains chiffres militants circulent sans méthode solide.", "Les données enregistrées par la police restent faibles et ne donnent qu'une image partielle."],
 contre=[
  ("On ne peut plus draguer.", "La loi ne vise pas le fait d'aborder poliment quelqu'un, mais le fait d'imposer à une personne un propos ou un comportement à connotation sexuelle ou sexiste. Les enquêtes de l'Ined montrent qu'il s'agit surtout de sifflements, d'insultes et de filatures."),
  ("Ce sont les féministes qui gonflent les chiffres.", "Les chiffres viennent de l'Ined, institut public, et du SSMSI, service statistique du ministère de l'Intérieur. Le chiffre fragile de « 100 % » est connu comme non représentatif, mais les enquêtes sérieuses trouvent déjà un quart des femmes concernées chaque année."),
  ("De toute façon, c'est la faute des immigrés.", "Les données disponibles décrivent des auteurs presque toujours masculins, surtout dans les grandes villes et les transports ; aucune des sources lues ne réduit ce phénomène à une origine. Lutter contre le harcèlement, c'est sanctionner tous les harceleurs."),
 ],
 questions=["As-tu demandé aux femmes de ton entourage si elles avaient déjà été suivies ou interpellées dans la rue ?", "Accepterais-tu que ta fille ou ta sœur soit sifflée et suivie en rentrant chez elle ?"],
 limites=["L'enquête Virage date de 2015 ; aucune enquête de victimation plus récente sur l'espace public n'a pu être lue en entier.", "Les chiffres de 2025 viennent d'un article de Maire-info citant le SSMSI : la publication du SSMSI n'a pas pu être ouverte (site du ministère inaccessible).", "Le communiqué de l'Ined et plusieurs documents longs ont été lus à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot.", "Les données de police dépendent fortement du dépôt de plainte et de la verbalisation : leur hausse peut refléter une meilleure prise en compte autant qu'une hausse des faits."],
 publics={'convaincus': "Ce n'est pas une affaire de militantes : c'est l'Ined, un institut public, qui a mesuré qu'un quart des femmes sont harcelées dans l'espace public chaque année, et la police qui enregistre des milliers de faits, avec presque toujours des hommes mis en cause. Tu as raison de te méfier de certains chiffres militants, mais les enquêtes sérieuses suffisent. Demande aux femmes autour de toi.",
  'indecis': "Tu as raison de vouloir des chiffres fiables. Selon l'enquête Virage de l'Ined, un quart des femmes ont subi un fait de harcèlement ou de violence dans l'espace public en un an, et deux tiers des jeunes Franciliennes. La loi ne punit pas la drague polie, mais les comportements qui intimident ou humilient."},
 a_actualiser='2027-04-30', raison="Bilan annuel du SSMSI sur les outrages sexistes et sexuels et éventuelle nouvelle enquête de victimation.",
))

# 4 ── « Hollande a cassé la politique familiale, c'est pour ça que les Français font moins d'enfants » ──────────────
