FICHES.append(fiche(
 id='politique-familiale-hollande-natalite', affirmation="Hollande a cassé la politique familiale, c'est pour ça que les Français font moins d'enfants.", volet='social', sous_theme='Allocations familiales',
 mots_cles=['hollande a casse la politique familiale', 'modulation des allocations familiales', 'baisse de la natalite', 'quotient familial hollande', 'les francais font moins d enfants', 'natalite en berne', 'allocations familiales sous condition de ressources', 'politique nataliste', 'rearmement demographique', 'baisse des naissances la faute a hollande'],
 verdict='trompeur', fiabilite='debat',
 resume="Trompeur. Sous François Hollande, le plafond du quotient familial a été abaissé (2013 et 2014) et les allocations familiales ont été modulées selon les revenus (2015), ce qui a réduit les aides des familles les plus aisées. La baisse des naissances a commencé avant, vers 2010-2011, et touche toutes les catégories sociales et presque tous les pays européens : la France reste parmi les plus féconds de l'UE. Les démographes de l'Ined jugent impossible d'attribuer la baisse à une mesure : les aides financières jouent surtout sur le calendrier des naissances. Certains experts estiment toutefois que l'instabilité des aides a pu peser sur la confiance des familles.",
 contexte="La France a enregistré en 2025 plus de décès que de naissances, pour la première fois depuis 1945. La droite et l'extrême droite accusent souvent les réformes du quinquennat Hollande d'avoir « cassé » la politique familiale universelle et provoqué la chute de la natalité.",
 explication="On rappelle ce qui a réellement changé sous Hollande, le calendrier de la baisse des naissances, son ampleur en Europe, et ce que disent les démographes et les institutions sur l'effet des prestations sur la fécondité.",
 sources=[D_PF_INSEE, D_PF_VP, D_PF_SENAT, D_PF_AN_INED, D_PF_AN_CNAF, D_PF_AN_IGF, D_PF_PS],
 faits=[
  fait("Selon Vie publique, depuis le 1er juillet 2015, les allocations familiales sont divisées par deux au-delà de 6 000 € nets de revenus mensuels pour deux enfants, et par quatre au-delà de 8 000 € ; la mesure a réduit les allocations versées de 760 millions d'euros par an.", 'd_pf_vp', 'depuis 2015', 'France', "La réforme a bien réduit les aides, mais seulement pour les ménages aux revenus élevés : les familles modestes et moyennes ont gardé leurs allocations.", 'etabli', '6 000 €'),
  fait("Selon la commission des affaires sociales du Sénat (2017), le plafond du quotient familial a été abaissé deux fois, en 2013 et 2014, et la modulation a réduit fortement les prestations des familles en haut de l'échelle des revenus ; mais « la baisse du nombre de naissance ne peut être imputée aux mesures qui ont touché les prestations familiales ».", 'd_pf_senat', '2013-2017', 'France', "Même la commission sénatoriale, à majorité de droite, n'attribue pas la baisse des naissances à ces réformes.", 'etabli'),
  fait("Selon l'Insee, la France a compté 645 000 naissances en 2025, 24 % de moins qu'en 2010, et l'indicateur de fécondité est tombé à 1,56 enfant par femme, contre 2,02 en 2010 ; mais en 2023 la France avait encore le deuxième taux de fécondité de l'UE (1,65), pour une moyenne européenne de 1,38.", 'd_pf_insee', '2010-2025', 'France et Union européenne', "La baisse est réelle et forte, mais elle touche toute l'Europe, y compris des pays qui n'ont pas connu ces réformes, et la France reste au-dessus de la moyenne.", 'etabli', '1,56'),
  fait("Selon la Cnaf, auditionnée par l'Assemblée nationale en 2025, la baisse de la natalité est « engagée depuis 2011, puis très accentuée depuis 2014 », et les prestations ont un impact « réel, mais limité » sur la fécondité : elles « peuvent accélérer le rythme, mais sans forcément jouer sur la descendance finale ».", 'd_pf_an_cnaf', '2011-2025', 'France', "La baisse a commencé avant les réformes, et l'organisme qui verse les allocations juge lui-même leur effet limité.", 'etabli'),
  fait("Selon des chercheurs de l'Ined auditionnés par l'Assemblée nationale en 2025, « il est difficile d'établir un lien de causalité entre un outil de politique publique et la décision d'avoir un enfant » ; les freins les plus cités sont le coût d'un enfant et la conciliation avec le travail, et les intentions de fécondité baissent chez les hommes comme chez les femmes.", 'd_pf_an_ined', '2025', 'France', "La baisse des naissances tient d'abord à des changements profonds de société, pas à une seule mesure.", 'etabli'),
  fait("Selon Public Sénat, rendant compte d'une audition de l'Ined et de l'Insee au Sénat, le nombre idéal d'enfants chez les 30-34 ans est passé de 2,7 à la fin des années 1990 à 2,3 aujourd'hui, et le directeur de l'Ined estime que « cette baisse n'est pas conjoncturelle ».", 'd_pf_ps', 'fin des années 1990-2026', 'France', "Le désir d'enfant lui-même recule, ce qu'aucune allocation ne suffit à compenser.", 'etabli', '2,3'),
  fait("Fait défavorable : selon un inspecteur des finances auditionné par l'Assemblée nationale (décembre 2025), « il apparaît assez clairement que la politique familiale exerce un effet réel », et l'instabilité des dispositifs peut inciter à différer un projet d'enfant ; la Cnaf évoque aussi un « effet de halo » des réformes sur la confiance des familles.", 'd_pf_an_igf', '2013-2025', 'France', "Les réformes ont pu peser à la marge, en entamant la confiance dans la stabilité des aides, même si aucune étude ne montre qu'elles expliquent la baisse.", 'interpretation'),
 ],
 court="Non. Les réformes Hollande (quotient familial abaissé, allocations modulées au-delà de 6 000 € de revenus par mois) ont touché surtout les familles aisées. La baisse des naissances avait commencé vers 2010-2011, touche toute l'Europe, et la France reste parmi les pays les plus féconds de l'UE. Même la commission du Sénat juge que la baisse ne peut être imputée à ces mesures.",
 moyen="Sous Hollande, deux réformes ont réduit les aides des familles aisées : la baisse du plafond du quotient familial en 2013 et 2014, puis, en 2015, la division par deux ou par quatre des allocations familiales au-delà de 6 000 ou 8 000 € de revenus mensuels pour deux enfants. Les familles modestes et moyennes n'ont pas été concernées par la modulation.\n\nLa baisse des naissances a commencé vers 2010-2011, selon la Cnaf et le Sénat, et s'est accélérée à partir de 2014. Elle touche presque toute l'Europe : en 2023, la France restait deuxième de l'UE avec 1,65 enfant par femme, pour une moyenne de 1,38. Les démographes de l'Ined jugent impossible d'attribuer la baisse à une mesure : le coût des enfants, la conciliation avec le travail et un désir d'enfant en recul pèsent davantage. Certains experts estiment cependant que l'instabilité des aides a pu entamer la confiance des familles.",
 detaille="Commençons par les faits. Sous François Hollande, le plafond du quotient familial a été abaissé deux fois, en 2013 et en 2014, puis la loi de financement de la Sécurité sociale pour 2015 a modulé les allocations familiales : depuis juillet 2015, elles sont divisées par deux au-delà de 6 000 € nets de revenus mensuels pour deux enfants, et par quatre au-delà de 8 000 €. L'économie est de 760 millions d'euros par an. Ces réformes ont donc réduit les aides des familles les plus aisées, pas des familles modestes ou moyennes.\n\nLa natalité, elle, recule depuis plus longtemps. Selon la Cnaf, la baisse est engagée depuis 2011 et s'accentue depuis 2014 ; le Sénat la date de 2010. En 2025, l'Insee compte 645 000 naissances, 24 % de moins qu'en 2010, et un indicateur de fécondité de 1,56 enfant par femme. Mais le phénomène est européen : en 2023, la France avait le deuxième taux de fécondité de l'UE (1,65), pour une moyenne de 1,38.\n\nQue disent les spécialistes ? En 2017, la commission des affaires sociales du Sénat, à majorité de droite, écrivait que la baisse des naissances « ne peut être imputée » aux mesures sur les prestations. En 2025, les chercheurs de l'Ined ont expliqué aux députés qu'il est difficile d'établir un lien de causalité entre une mesure et la décision d'avoir un enfant, et que les aides financières jouent surtout sur le calendrier des naissances. Les freins cités sont le coût des enfants, la conciliation avec le travail, et un désir d'enfant qui recule : le nombre idéal d'enfants chez les 30-34 ans est passé de 2,7 à 2,3.\n\nIl serait malhonnête de dire que la politique familiale ne compte pas. Un inspecteur des finances estime qu'elle exerce « un effet réel », et la Cnaf évoque un « effet de halo » : l'instabilité des aides peut inquiéter même les familles non concernées. Mais les leviers jugés les plus efficaces par l'Ined sont l'égalité professionnelle, le partage des tâches parentales, des modes de garde accessibles et des aides stables. Une politique de gauche pour les familles, c'est d'abord des crèches, des logements et des salaires qui permettent de faire les enfants que l'on désire.",
 empathie="Voir le nombre de naissances baisser inquiète, pour l'avenir du pays comme pour le financement des retraites. Et beaucoup de familles ont le sentiment que les aides changent sans cesse.",
 legitimes=["Les réformes de 2013 à 2015 ont réellement réduit les aides de certaines familles.", "La natalité baisse fortement et le solde naturel est devenu négatif en 2025.", "L'instabilité des aides peut entamer la confiance des familles, selon certains experts."],
 contre=[
  ("La baisse a commencé juste après les réformes Hollande.", "Selon la Cnaf et le Sénat, elle a commencé vers 2010-2011, avant les réformes, puis s'est accélérée à partir de 2014. Et elle touche presque toute l'Europe."),
  ("Avant, la politique familiale était universelle, c'est ce qui faisait notre force.", "Les allocations restent versées à toutes les familles d'au moins deux enfants ; seuls les ménages au-delà de 6 000 € nets par mois touchent moins. Les démographes attribuent surtout la fécondité française aux aides à la conciliation entre travail et famille, comme les modes de garde."),
  ("Il suffit d'augmenter les allocations pour relancer les naissances.", "Selon l'Ined et la Cnaf, les aides financières font surtout avancer des naissances déjà prévues, sans forcément augmenter le nombre d'enfants. Les freins principaux sont le coût des enfants, la conciliation avec le travail et un désir d'enfant en recul."),
 ],
 questions=["Selon toi, est-ce que les familles qui gagnent plus de 6 000 € par mois renoncent à un enfant à cause des allocations ?", "Qu'est-ce qui pèse le plus sur les jeunes couples autour de toi : les allocations, le logement ou la garde des enfants ?"],
 limites=["Aucune étude économétrique évaluant précisément l'effet de la modulation de 2015 sur la fécondité n'a pu être lue ; les avis rapportés viennent d'auditions parlementaires.", "Les comptes rendus d'audition ont été lus à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot.", "La note du Haut-Commissariat à la Stratégie et au Plan sur la dénatalité (2026) n'a pas pu être ouverte ; aucun rapport du HCFEA ni de la Cour des comptes n'a été lu.", "La fiche de Vie publique sur la modulation n'est pas datée."],
 publics={'convaincus': "Les réformes Hollande ont bien réduit les aides, mais surtout pour les familles au-delà de 6 000 € par mois. La baisse des naissances avait commencé avant, elle touche toute l'Europe, et même la commission du Sénat, à droite, dit qu'elle ne peut pas être imputée à ces mesures. Si on veut des enfants, il faut surtout des crèches, des logements et de la stabilité.",
  'indecis': "Ton inquiétude est fondée : la natalité baisse fortement depuis une quinzaine d'années. Mais les démographes de l'Ined expliquent qu'aucune mesure ne suffit à l'expliquer : coût des enfants, difficulté à concilier travail et famille, désir d'enfant en recul. Des aides stables et des services de garde comptent plus que des primes."},
 a_actualiser='2027-01-31', raison="Prochain bilan démographique de l'Insee et rapport de la mission d'information de l'Assemblée nationale sur la natalité.",
))

# 5 ── « Les journalistes sont tous de gauche » ──────────────
D_JG_LAFARGE = ('d_jg_lafarge', src("Géraud Lafarge : « La sélection sociale dans les écoles de journalisme »", "L'Etudiant (EducPros)", '28 novembre 2011',
  'https://www.letudiant.fr/educpros/entretiens/geraud-lafarge-maitre-de-conferences-en-info-com-iut-de-lannion-la-selection-sociale-dans.html',
  "Entretien avec le sociologue Géraud Lafarge (IUT de Lannion) sur son enquête auprès des étudiants des écoles de journalisme reconnues : 52 % ont un père cadre ou de profession intellectuelle supérieure (18,5 % de la population active masculine en 2005), 10,4 % sont enfants d'ouvriers (35 % de la population active). Ces étudiants se disent « très majoritairement à gauche » et veulent surtout travailler dans les médias nationaux d'information générale.",
  "Entretien avec un chercheur dans un média spécialisé dans l'enseignement supérieur.", 'secondaire'))
