FICHES.append(fiche(
 id='journalistes-tous-de-gauche', affirmation="Les journalistes sont tous de gauche.", volet='politique', sous_theme='Médias',
 mots_cles=['les journalistes sont tous de gauche', 'medias de gauche', 'journalistes gauchistes', 'merdias', 'service public de gauche', 'france inter de gauche', 'ecoles de journalisme de gauche', 'medias aux mains des milliardaires', 'pluralisme arcom', 'bollore medias'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Il n'existe pas de mesure fiable et récente des opinions politiques des quelque 35 000 journalistes encartés. Une enquête universitaire montre que les étudiants des écoles de journalisme reconnues se disent très majoritairement à gauche, mais ces écoles ne forment qu'une minorité des journalistes, et les opinions personnelles ne disent pas tout de ce qui est publié. Les grands médias privés appartiennent à quelques industriels et milliardaires, dont certains promeuvent une ligne de droite ou d'extrême droite. Le régulateur a mis en demeure en 2026 aussi bien Radio France (RN sous-représenté en journée) que CNews (déséquilibre du pluralisme).",
 contexte="L'idée d'un journalisme acquis à la gauche est un classique de la droite et de l'extrême droite, qui l'utilisent pour disqualifier les informations qui les dérangent, notamment sur le service public. Le débat s'est intensifié avec la montée de médias d'opinion comme CNews et les décisions de l'Arcom sur le pluralisme.",
 explication="On distingue ce que l'on sait des opinions des journalistes (très peu de données solides), qui forme les journalistes, qui possède les médias, et ce que constate le régulateur sur le pluralisme à l'antenne.",
 sources=[D_JG_LAFARGE, D_JG_LETEINT, D_JG_CCIJP, D_JG_SENAT, D_JG_PS, D_JG_AFP, D_JG_CNEWS],
 faits=[
  fait("Selon un bilan de la CCIJP rapporté par CB News, 34 948 cartes de presse ont été délivrées en 2024 ; environ 26 % des journalistes encartés sont pigistes ou en CDD.", 'd_jg_ccijp', '2024', 'France', "La profession compte des dizaines de milliers de personnes aux situations très diverses, souvent précaires : parler de « tous les journalistes » n'a pas de sens.", 'estimation', '34 948'),
  fait("Fait défavorable : selon le sociologue Géraud Lafarge, interrogé par EducPros, les étudiants des écoles de journalisme reconnues qu'il a enquêtés se disent « très majoritairement à gauche » ; 52 % ont un père cadre ou de profession intellectuelle supérieure, et 10,4 % sont enfants d'ouvriers.", 'd_jg_lafarge', 'années 2000', 'écoles de journalisme reconnues', "Il existe bien une orientation à gauche chez une partie des futurs journalistes, ainsi qu'une forte sélection sociale ; c'est un constat à reconnaître, pas à nier.", 'interpretation', '52 %'),
  fait("Selon l'enquête de Christine Leteinturier (Paris 2) présentée par EducPros, les diplômés des écoles reconnues ne représentaient que 21,6 % des nouveaux titulaires de la carte de presse en 2008.", 'd_jg_leteint', '2008', 'France', "Les écoles les plus étudiées ne forment qu'une minorité des journalistes : on ne peut pas généraliser leurs étudiants à toute la profession.", 'interpretation', '21,6 %'),
  fait("Selon CB News, la commission d'enquête du Sénat sur la concentration des médias (2022) a auditionné notamment Bernard Arnault, Vincent Bolloré, Arnaud Lagardère, Xavier Niel, Patrick Drahi et Martin Bouygues, propriétaires de grands groupes, et a proposé de renforcer l'indépendance des rédactions face aux actionnaires.", 'd_jg_senat', '2022', 'France', "Ce sont des industriels et des milliardaires, et non les journalistes, qui possèdent la plupart des grands médias privés et nomment leurs dirigeants.", 'estimation'),
  fait("Selon Public Sénat, le rapporteur David Assouline dénonce la « concentration verticale » des médias, et la droite sénatoriale s'est opposée à des mesures comme un droit de veto des rédactions sur la nomination de leur directeur de l'information.", 'd_jg_ps', '2022', 'France', "Les journalistes ont peu de pouvoir face aux propriétaires sur la ligne éditoriale.", 'etabli'),
  fait("Fait défavorable : selon l'AFP, l'Arcom a mis en demeure Radio France en juin 2026, car près de 60 % du temps de parole du RN sur France Inter et plus de 70 % sur franceinfo avaient été diffusés entre minuit et 6 heures au premier trimestre 2026 ; Radio France invoque une erreur de logiciel de décompte.", 'd_jg_afp', '2026', 'France', "Le service public a lui aussi des obligations de pluralisme et peut être rappelé à l'ordre : la critique n'est pas sans fondement.", 'etabli', '60 %'),
  fait("Selon The Media Leader, l'Arcom a mis en demeure CNews en juin 2026 pour un « déséquilibre manifeste et durable » dans le pluralisme des courants de pensée et d'opinion, après une saisine de Reporters sans frontières ; CNews conteste devant le Conseil d'État.", 'd_jg_cnews', '2025-2026', 'France', "Les manquements au pluralisme existent dans les deux sens, et une des principales chaînes d'information est sanctionnée pour une ligne marquée à droite.", 'estimation'),
 ],
 court="Non. Aucune donnée fiable et récente ne mesure les opinions des quelque 35 000 journalistes. Les étudiants des grandes écoles de journalisme se disent surtout de gauche, mais ces écoles ne forment qu'une minorité de la profession. Et les grands médias privés appartiennent à des milliardaires comme Bolloré, Arnault ou Bouygues. En 2026, le régulateur a d'ailleurs mis en demeure aussi bien Radio France que CNews.",
 moyen="On ne sait pas mesurer sérieusement le vote des journalistes : il n'existe pas d'enquête récente et fiable sur leurs opinions. Ce que l'on sait : une enquête du sociologue Géraud Lafarge montre que les étudiants des écoles reconnues se disent très majoritairement à gauche, et viennent souvent de milieux aisés. Mais ces écoles ne représentaient que 21,6 % des nouveaux titulaires de la carte de presse en 2008, sur une profession de près de 35 000 personnes, dont un quart de pigistes ou de CDD.\n\nSurtout, ce ne sont pas les journalistes qui possèdent les médias. La commission d'enquête du Sénat de 2022 a auditionné les propriétaires des grands groupes privés : Bolloré, Arnault, Lagardère, Niel, Drahi, Bouygues. Et le régulateur sanctionne dans les deux sens : en 2026, l'Arcom a mis en demeure Radio France pour avoir relégué la parole du RN la nuit, et CNews pour un déséquilibre « manifeste et durable » du pluralisme.",
 detaille="Commençons par ce que l'on ne sait pas. Il n'existe pas d'enquête récente et fiable mesurant les opinions politiques des journalistes en France. Les sondages qui circulent sont anciens, partiels ou réalisés sur des échantillons non représentatifs. Or la profession est vaste et diverse : selon la CCIJP, 34 948 cartes de presse ont été délivrées en 2024, dont environ un quart à des pigistes ou des CDD, qui travaillent dans la presse locale, spécialisée, sportive, économique ou audiovisuelle.\n\nCe que l'on sait, en revanche, mérite d'être reconnu. Le sociologue Géraud Lafarge a montré que les étudiants des écoles de journalisme reconnues se disent très majoritairement à gauche, et qu'ils viennent souvent de milieux favorisés : 52 % ont un père cadre, contre 10,4 % d'enfants d'ouvriers. Mais ces écoles ne forment qu'une minorité des journalistes : 21,6 % des nouveaux titulaires de la carte en 2008, selon l'enquête de Christine Leteinturier. Et les opinions personnelles d'un journaliste ne décident pas seules de ce qui est publié.\n\nCar le pouvoir dans les médias appartient d'abord à leurs propriétaires. La commission d'enquête du Sénat sur la concentration des médias a auditionné en 2022 Bernard Arnault, Vincent Bolloré, Arnaud Lagardère, Xavier Niel, Patrick Drahi et Martin Bouygues. Son rapporteur dénonce une concentration qui fragilise le pluralisme, et des propositions pour donner aux rédactions un droit de regard sur la nomination de leurs dirigeants ont été rejetées par la droite sénatoriale.\n\nEnfin, le régulateur constate des déséquilibres dans les deux sens. En juin 2026, l'Arcom a mis en demeure Radio France parce que l'essentiel du temps de parole du RN sur France Inter et franceinfo était diffusé la nuit, et CNews pour un déséquilibre « manifeste et durable » du pluralisme. Défendre une information libre, c'est garantir l'indépendance des rédactions face aux actionnaires comme au pouvoir politique, et un service public pluraliste, pas désigner les journalistes comme ennemis.",
 empathie="Beaucoup de gens ont le sentiment que les médias ne parlent pas comme eux ni de leurs préoccupations, et que les journalistes viennent d'un autre monde social. Ce sentiment n'est pas absurde : la profession est en partie socialement sélective.",
 legitimes=["Les étudiants des grandes écoles de journalisme viennent souvent de milieux favorisés et se disent majoritairement à gauche, selon une enquête universitaire.", "Le service public a été rappelé à l'ordre par l'Arcom pour la sous-représentation du RN en journée.", "La défiance envers les médias est forte et mérite d'être prise au sérieux."],
 contre=[
  ("Tout le monde sait que les journalistes votent à gauche.", "Aucune enquête récente et fiable ne mesure le vote des 35 000 journalistes encartés. On sait seulement que les étudiants des écoles reconnues, minoritaires dans la profession, se disent surtout de gauche."),
  ("France Inter, c'est la radio de la gauche.", "L'Arcom a bien mis en demeure Radio France en 2026 pour la place du RN la nuit ; la radio invoque une erreur de décompte. Mais la même autorité a aussi mis en demeure CNews pour un déséquilibre « manifeste et durable » : le pluralisme s'impose à tous."),
  ("Les médias sont aux mains de la gauche.", "Les grands groupes privés appartiennent à des industriels et milliardaires comme Bolloré, Arnault, Bouygues ou Drahi, auditionnés par le Sénat en 2022. Ce sont eux qui nomment les directions, pas les journalistes."),
 ],
 questions=["Qui possède, selon toi, les chaînes et journaux que tu regardes ou lis le plus ?", "Un journaliste de presse locale ou sportive, il est forcément de gauche lui aussi ?"],
 limites=["Aucune enquête scientifique récente sur les opinions politiques des journalistes en France n'a pu être lue : la fiche ne peut ni confirmer ni exclure une majorité de gauche dans la profession.", "Les données de Géraud Lafarge portent sur des étudiants des années 2000 et sont connues par un entretien de 2011 ; l'article scientifique original (HAL) n'a pas pu être ouvert.", "La part des écoles reconnues (21,6 %) date de 2008.", "Les chiffres de la CCIJP et les propositions du Sénat sont connus par la presse spécialisée (CB News) ; les décisions de l'Arcom n'ont pas été lues sur le site du régulateur.", "Le rapport du Sénat de 2022 sur la concentration des médias n'a pas été lu directement."],
 publics={'convaincus': "Tu as en partie raison : une enquête universitaire montre que les étudiants des grandes écoles de journalisme se disent surtout de gauche, et l'Arcom a rappelé Radio France à l'ordre. Mais ces écoles forment une minorité des 35 000 journalistes, et ce sont des milliardaires comme Bolloré ou Arnault qui possèdent les grands médias privés. Le même régulateur a d'ailleurs mis CNews en demeure.",
  'indecis': "Personne ne mesure sérieusement le vote des journalistes. On sait que les grandes écoles recrutent surtout dans des milieux favorisés et plutôt à gauche, mais que les médias privés appartiennent à quelques grands industriels. Pour s'informer, mieux vaut regarder qui possède un média et comparer plusieurs sources."},
 a_actualiser='2027-06-30', raison="Décisions du Conseil d'État sur la mise en demeure de CNews, nouvelles données de la CCIJP et éventuelle enquête sur les journalistes.",
))


